WITH valid AS (SELECT id, full_name, dept_id, manager_id, job_title, hire_date, level, LOWER(job_title) AS job_title_lower, CASE WHEN salary >= 143000 THEN 'High' WHEN salary >= 65000 THEN 'Medium' ELSE 'Low' END AS salary_band, COALESCE(level, 'N/A') AS level_filled FROM employees WHERE manager_id IS NOT NULL) SELECT s.id, s.dept_id, s.manager_id, s.hire_date, s.level, s.level_filled, p.location, p.dept_name, p.budget FROM valid s LEFT JOIN departments p ON s.dept_id = p.id;
